package com.zpantry.subscription.api;
import com.zpantry.common.api.ApiResponse; import com.zpantry.subscription.service.SubscriptionService; import com.zpantry.user.security.AuthenticatedUserResolver; import jakarta.validation.Valid; import java.time.Instant; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import static com.zpantry.subscription.api.SubscriptionDtos.*;
@RestController @RequestMapping("/api/me/subscription") public class SubscriptionController { private final SubscriptionService service; private final AuthenticatedUserResolver users; public SubscriptionController(SubscriptionService s,AuthenticatedUserResolver u){service=s;users=u;} private java.util.UUID id(Authentication a){return users.resolve(a).orElseThrow().userId();} private <T> ApiResponse<T> ok(T d,String m){return new ApiResponse<>(true,m,d,null,"",Instant.now());}
 @GetMapping public ApiResponse<SubscriptionResponse> current(Authentication a){return ok(service.current(id(a)),"");} @GetMapping("/plans") public ApiResponse<java.util.List<PlanResponse>> plans(){return ok(service.plans(),"");} @PostMapping("/checkout") public ResponseEntity<ApiResponse<CheckoutResponse>> checkout(Authentication a,@Valid @RequestBody CheckoutRequest r){try{return ResponseEntity.ok(ok(service.checkout(id(a),r.provider()),"Payment order created."));}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(new ApiResponse<>(false,e.getMessage(),null,null,"",Instant.now()));}} @PostMapping("/cancel") public ApiResponse<Void> cancel(Authentication a){service.cancel(id(a));return ok(null,"Subscription cancelled.");}}
